changeSet.sql:
INSERT INTO plugins (
identifier, name, description,
javascriptModuleFile,
functionsViewTemplate,
settingsViewTemplate,
namelocalizationkey,
settingsPermission, functionsPermission, deviceFunctionsPermission,
enabledForDevice
)
VALUES (
'devicereset', 'Device Reset', 'Factory reset, reboot, lock and password reset',
'app/components/plugins/devicereset/devicereset.module.js',
'app/components/plugins/devicereset/views/devicereset.html',
NULL,
'plugin.devicereset.localization.key.name',
NULL,
NULL,
NULL,
TRUE
);

-- Permissions are granted to the administrator roles only; assign them to other roles explicitly
INSERT INTO permissions (name, description) VALUES ('plugin_devicereset_reset', 'Can factory-reset devices');
INSERT INTO userRolePermissions (roleId, permissionId) VALUES (1, currval('permissions_id_seq'));
INSERT INTO userRolePermissions (roleId, permissionId) VALUES (2, currval('permissions_id_seq'));
INSERT INTO permissions (name, description) VALUES ('plugin_devicereset_lock', 'Can lock and unlock devices');
INSERT INTO userRolePermissions (roleId, permissionId) VALUES (1, currval('permissions_id_seq'));
INSERT INTO userRolePermissions (roleId, permissionId) VALUES (2, currval('permissions_id_seq'));
INSERT INTO permissions (name, description) VALUES ('plugin_devicereset_reboot', 'Can reboot devices');
INSERT INTO userRolePermissions (roleId, permissionId) VALUES (1, currval('permissions_id_seq'));
INSERT INTO userRolePermissions (roleId, permissionId) VALUES (2, currval('permissions_id_seq'));
INSERT INTO permissions (name, description) VALUES ('plugin_devicereset_password', 'Can reset device passwords');
INSERT INTO userRolePermissions (roleId, permissionId) VALUES (1, currval('permissions_id_seq'));
INSERT INTO userRolePermissions (roleId, permissionId) VALUES (2, currval('permissions_id_seq'));

CREATE TABLE plugin_devicereset_status (
    deviceId INT NOT NULL CONSTRAINT plugin_devicereset_status_pr_key PRIMARY KEY
        REFERENCES devices (id) ON DELETE CASCADE,
    factoryReset BOOLEAN NOT NULL DEFAULT FALSE,
    reboot BOOLEAN NOT NULL DEFAULT FALSE,
    lock BOOLEAN NOT NULL DEFAULT FALSE,
    lockMessage TEXT,
    passwordReset TEXT,
    requestedAt BIGINT,
    requestedBy INT,
    resetConfirmedAt BIGINT,
    rebootConfirmedAt BIGINT,
    passwordConfirmedAt BIGINT
);

changeSet.rollback:
DELETE FROM plugins WHERE identifier = 'devicereset';
DELETE FROM permissions WHERE name = 'plugin_devicereset_reset';
DELETE FROM permissions WHERE name = 'plugin_devicereset_lock';
DELETE FROM permissions WHERE name = 'plugin_devicereset_reboot';
DELETE FROM permissions WHERE name = 'plugin_devicereset_password';
DROP TABLE plugin_devicereset_status;
